--
-- Table structure for table `signals`
--

DROP TABLE IF EXISTS `signals`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `signals` (
  `id` int NOT NULL AUTO_INCREMENT,
  `signal_id` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `symbol` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `timeframe` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `signal` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `confidence` float NOT NULL,
  `entry` float NOT NULL,
  `stop_loss` float NOT NULL,
  `take_profit` float NOT NULL,
  `timestamp` datetime NOT NULL,
  `created_at` datetime NOT NULL,
  `ema20` float DEFAULT NULL,
  `ema50` float DEFAULT NULL,
  `ema200` float DEFAULT NULL,
  `rsi14` float DEFAULT NULL,
  `macd_line` float DEFAULT NULL,
  `macd_signal` float DEFAULT NULL,
  `macd_histogram` float DEFAULT NULL,
  `atr14` float DEFAULT NULL,
  `candle_body_pct` float DEFAULT NULL,
  `upper_wick_pct` float DEFAULT NULL,
  `lower_wick_pct` float DEFAULT NULL,
  `dist_ema20` float DEFAULT NULL,
  `dist_ema50` float DEFAULT NULL,
  `dist_ema200` float DEFAULT NULL,
  `trend_strength` float DEFAULT NULL,
  `momentum_score` float DEFAULT NULL,
  `session` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `spread` float DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `signal_id` (`signal_id`),
  KEY `ix_signal_timestamp` (`timestamp`),
  KEY `ix_signal_symbol_tf` (`symbol`,`timeframe`)
) ENGINE=InnoDB AUTO_INCREMENT=361 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

